INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗患病", "description": "天顺八年正月乙卯，《明史》本纪记明英宗朱祁镇患病。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年正月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6f255b72-31a3-5f70-bd0a-d7862a61c73c"}, {"title": "皇太子朱见深在文华殿代行朝政", "description": "天顺八年正月己未，明英宗患病后，皇太子朱见深在文华殿代行朝政。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年正月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e29517b-486b-564d-85f3-9aca0e981fa0"}, {"title": "明英宗在遗诏中停止宫妃殉葬", "description": "天顺八年正月己巳，明英宗朱祁镇病重，在遗诏中下令停止令宫妃殉葬。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年正月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f237b1b5-a22b-5920-ad74-60670fc1d1db"}, {"title": "明英宗朱祁镇去世", "description": "天顺八年正月庚午，明英宗朱祁镇去世。《明史》本纪记其年三十八。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年正月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5bdf8e1a-0acf-500d-b2e8-6a29ce39df3a"}, {"title": "明廷为朱祁镇上尊谥，定庙号为英宗", "description": "天顺八年二月乙未，朝廷给已去世的朱祁镇上尊谥，庙号定为英宗。卷末校记指出，正文日期由原作三月改为二月。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ed643588-6618-5b22-aedc-e05aa0d01665"}, {"title": "明廷将明英宗朱祁镇安葬于裕陵", "description": "《英宗后纪》在上尊谥条后记明英宗朱祁镇葬于裕陵。《宪宗本纪》记安葬的确日为天顺八年五月庚申。", "start_year": 1464, "end_year": 1464, "time_original": "天顺八年五月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aac54348-0628-5a7b-83cb-97819af70f24"}, {"title": "石彪从定远伯进封为定远侯", "description": "明廷将定远伯石彪进封为定远侯。《英宗后纪》将此事写在天顺三年正月战报之后，卷末校记所引功臣世表及《英宗实录》记在四月己巳。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年四月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e4d8ac1-72f8-54bc-9ef9-da43a70f62d8"}, {"title": "梧州失守，已经退休的布政使宋钦遇害", "description": "天顺七年十一月癸酉，起事武装攻陷梧州，已经退休的布政使宋钦遇害。", "start_year": 1464, "end_year": 1464, "time_original": "天顺七年十一月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e42a7026-7cf0-5e12-8b77-7cb76faafe6c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

